 1→import { createContext, useContext } from 'react';
 2→import type { ChatMessage } from '../types';
 3→
 4→interface AgentContextValue {
 5→  messages: ChatMessage[];
 6→  isStreaming: boolean;
 7→  sendMessage: (text: string) => void;
 8→  editMessage: (messageIndex: number, newContent: string) => void;
 9→  deleteMessage: (messageIndex: number) => void;
10→  clearMessages: () => void;
11→}
12→
13→export const AgentContext = createContext<AgentContextValue>({
14→  messages: [],
15→  isStreaming: false,
16→  sendMessage: () => {},
17→  editMessage: () => {},
18→  deleteMessage: () => {},
19→  clearMessages: () => {},
20→});
21→
22→export function useAgent() {
