 60→export async function runAgentLoop(
 61→  message: string,
 62→  agentSessionId: string | null,
 63→  langfuseSessionId: string | null,
 64→  conversationHistory: { role: string; content: string }[] | null,
 65→  callbacks: AgentCallbacks,
 66→  signal?: AbortSignal,
 67→  userSessionId?: string,
 68→): Promise<void> {
 69→  try {
 70→    const response = await fetch('/api/chat', {
 71→      method: 'POST',
 72→      headers: {
 73→        'Content-Type': 'application/json',
 74→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
 75→      },
 76→      body: JSON.stringify({
 77→        message,
 78→        session_id: agentSessionId,
 79→        langfuse_session_id: langfuseSessionId,
 80→        conversation_history: conversationHistory ?? [],
 81→      }),
 82→      signal,
 83→    });
 84→
 85→    if (!response.ok) {
 86→      const errorText = await response.text();
 87→      callbacks.onError(`Server error: ${errorText}`);
 88→      return;
 89→    }
 90→
 91→    await streamSSE(response, callbacks, signal);
 92→  } catch (e: unknown) {
 93→    if (signal?.aborted) return;
 94→    const msg = e instanceof Error ? e.message : 'Connection failed';
 95→    callbacks.onError(msg);
 96→  }
 97→}
