136→function handleSSEEvent(
137→  eventType: string,
138→  data: Record<string, unknown>,
139→  callbacks: AgentCallbacks,
140→) {
141→  switch (eventType) {
142→    case 'thinking':
143→    case 'answer':
144→      callbacks.onTextChunk(data.text as string);
145→      break;
146→    case 'thinking_done':
147→      callbacks.onThinkingDone();
148→      break;
149→    case 'tool_call':
150→      callbacks.onToolCall({
151→        toolCallId: (data.id as string) ?? '',
152→        toolName: (data.name as string) ?? undefined,
153→        sql: (data.sql as string) ?? '',
154→        command: (data.command as string) ?? undefined,
155→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
156→        columns: [],
157→        rows: [],
158→        rowCount: 0,
159→      });
160→      break;
161→    case 'tool_result': {
162→      const result: ToolCallResult = {
163→        toolCallId: (data.id as string) ?? '',
164→        toolName: (data.name as string) ?? undefined,
165→        sql: (data.sql as string) ?? '',
166→        columns: (data.columns as string[]) ?? [],
167→        rows: (data.rows as Record<string, unknown>[]) ?? [],
168→        rowCount: (data.rowCount as number) ?? 0,
169→        error: (data.error as string) ?? undefined,
170→        output: (data.output as string) ?? undefined,
171→        rawContent: (data.content as string) ?? undefined,
172→      };
173→      callbacks.onToolResult(result);
174→      break;
175→    }
176→    case 'done':
177→      callbacks.onDone((data.session_id as string) ?? null);
178→      break;
179→    case 'error':
180→      callbacks.onError((data.message as string) ?? 'Unknown error');
181→      break;
182→  }
183→}
