 31→function AppContent({
 32→  tables,
 33→  refreshTables,
 34→  sessionId,
 35→}: {
 36→  tables: TableInfo[];
 37→  refreshTables: () => Promise<void>;
 38→  sessionId: string;
 39→}) {
 40→  const { theme, toggleTheme } = useTheme();
 41→  const { language, setLanguage, t } = useTranslation();
 42→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 43→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 44→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 45→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 46→  );
 47→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 48→  const [agentOpen, setAgentOpen] = useState(true);
 49→
 50→  useEffect(() => {
 51→    document.title = t('appTitle');
 52→  }, [t]);
 53→
 54→  useEffect(() => {
 55→    if (tables.length === 0) {
 56→      setQueryResult(null);
 57→      setError(null);
 58→      setEditorQuery(undefined);
 59→    }
 60→  }, [tables]);
 61→
 62→  const errorMessage = error
 63→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 64→    : null;
 65→
 66→  const handleAgentToggle = () => {
 67→    setAgentOpen((prev) => !prev);
 68→  };
 69→
 70→  const handleLoadSample = useCallback(async () => {
 71→    setError(null);
 72→    try {
 73→      const response = await fetch('/api/upload/sample', { method: 'POST', headers: { 'X-Session-ID': sessionId } });
 74→      if (!response.ok) throw new Error('Failed to load sample dataset');
 75→      await refreshTables();
 76→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 77→    } catch (e) {
 78→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 79→    }
 80→  }, [refreshTables, sessionId]);
 81→
 82→  const handleFileUpload = useCallback(
 83→    async (files: File[]) => {
 84→      setError(null);
 85→
 86→      // Check for duplicate filenames within the batch
 87→      const batchDuplicates = findDuplicateFileNames(files);
 88→      if (batchDuplicates.length > 0) {
 89→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
 90→        return;
 91→      }
 92→
 93→      // Check for filenames that match already-uploaded table names
 94→      const existingNames = new Set(tables.map((tbl) => tbl.name));
 95→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
 96→      if (alreadyUploaded.length > 0) {
 97→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
 98→        return;
 99→      }
100→
101→      let lastName = '';
102→      try {
103→        for (const file of files) {
104→          const formData = new FormData();
105→          formData.append('file', file);
106→          const response = await fetch('/api/upload', {
107→            method: 'POST',
108→            headers: { 'X-Session-ID': sessionId },
109→            body: formData,
110→          });
111→          if (!response.ok) {
112→            const errorData = await response.json();
113→            throw new Error(errorData.detail || 'Failed to upload file');
114→          }
115→          const result = await response.json();
116→          // Handle both single table and array of tables (Excel with multiple sheets)
117→          if (Array.isArray(result)) {
118→            lastName = result[result.length - 1]?.name || '';
119→          } else {
120→            lastName = result.name;
121→          }
122→        }
123→        await refreshTables();
124→        if (lastName) {
125→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
126→        }
127→      } catch (e) {
128→        setError(e instanceof Error ? e.message : 'Failed to upload file');
129→      }
130→    },
131→    [refreshTables, sessionId, tables]
132→  );
133→
134→  const handleQueryExecute = useCallback(
135→    async (sql: string) => {
136→      setError(null);
137→      setQueryResult(null);
138→      try {
139→        const start = performance.now();
140→        const response = await fetch('/api/query', {
141→          method: 'POST',
142→          headers: { 'Content-Type': 'application/json', 'X-Session-ID': sessionId },
143→          body: JSON.stringify({ sql }),
144→        });
145→        const elapsed = performance.now() - start;
146→
147→        if (!response.ok) {
148→          const errorData = await response.json();
149→          throw new Error(errorData.detail || 'Query execution failed');
150→        }
151→
152→        const result = await response.json();
153→        setQueryResult({
154→          columns: result.columns,
155→          rows: result.rows,
156→          rowCount: result.rowCount,
157→          executionTimeMs: elapsed,
158→          resultType: result.resultType,
159→        });
160→        await refreshTables();
161→      } catch (e) {
162→        setError(e instanceof Error ? e.message : 'Query execution failed');
163→      }
164→    },
165→    [refreshTables, sessionId]
166→  );
167→
168→  const handleTableClick = useCallback((tableName: string) => {
169→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
170→  }, []);
171→
172→  const handleTableDelete = useCallback(async (tableName: string) => {
173→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
174→    try {
175→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
176→        method: 'DELETE',
177→        headers: { 'X-Session-ID': sessionId },
178→      });
179→      if (!response.ok) throw new Error('Failed to delete table');
180→      await refreshTables();
181→    } catch (e) {
182→      setError(e instanceof Error ? e.message : 'Failed to delete table');
183→    }
184→  }, [refreshTables, t, sessionId]);
185→
186→  const handleDeleteAll = useCallback(async () => {
187→    if (tables.length === 0) return;
188→    if (!confirm(t('deleteAllTablesConfirm'))) return;
189→    try {
190→      for (const table of tables) {
191→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
192→          method: 'DELETE',
193→          headers: { 'X-Session-ID': sessionId },
194→        });
195→        if (!response.ok) throw new Error('Failed to delete table');
196→      }
